'use strict';
window.OrthodoxEditorial=(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let controller=null,sourceMap=new Map(),release=null;
 const sourceType=s=>s.type||'Type not recorded';
 function sourceContext(id){const s=sourceMap.get(id);if(!s)return '';const record=release?.sources?.find(r=>r.id===id);return `<details class="source-context"><summary>Source context · ${esc(sourceType(s))}</summary><dl><dt>Author / issuing body</dt><dd>${esc(s.author||'Not recorded')}</dd><dt>Edition / translation</dt><dd>${esc([s.edition,s.translator].filter(Boolean).join(' · ')||'Not recorded')}</dd><dt>Date</dt><dd>${esc(s.year||s.date||'Not recorded in this catalogue')}</dd><dt>Audience / context</dt><dd>${esc(s.audience||s.context||'Read the publication and cited location for its audience and context.')}</dd><dt>Tradition / jurisdiction</dt><dd>${esc(s.tradition||'Not recorded')}</dd><dt>Text verification</dt><dd>${esc(record?.verification||s.textVerification||'Bibliographic record; quotation verification is recorded separately.')}</dd><dt>Theological review</dt><dd>No independent theological review recorded in this edition.</dd></dl><a href="#/source-guide">Understanding source types</a></details>`;}
 async function load(sources){sourceMap=sources instanceof Map?sources:new Map(sources.map(s=>[s.id,s]));try{const response=window.OrthodoxResources?{ok:true,json:()=>window.OrthodoxResources.json('content/release-inventory.json')}:await fetch('content/release-inventory.json');if(response.ok)release=await response.json();}catch{}return release;}
 async function mount({root,sources,kind='editorial'}){unmount();controller=new AbortController();const signal=controller.signal;if(kind!=='privacy')await load(sources);else sourceMap=sources;if(!root.isConnected||signal.aborted)return;
   if(kind==='privacy'){root.innerHTML=`<h1>Privacy and saved data</h1><article class="privacy-text"><h2>Local reading</h2><p>Guest notes, progress, highlights, questions, prayer favorites, and reading positions are stored in this browser profile. Reading content is available without an account. This app adds no analytics or advertising.</p><h2>Optional accounts</h2><p>When an account service is configured, signing in permits synchronization of your study data with that service. Your guest data remains separate until you choose to import it. Corrections are submitted separately and can be seen by authorized editors and reviewers. A question in your notebook is not submitted to anyone.</p><h2>Sign-in providers</h2><p>If enabled, Google, Facebook, or Apple verifies your identity through Supabase Auth. Email/password accounts use the same account service. Social sign-in does not itself subscribe you to project emails.</p><h2>Email updates</h2><p>The optional checkbox asks permission for occasional updates about Holy Apostolic. It starts unchecked. Your choice does not affect access or saved progress. Change it in Account at any time. A verified account email, the agreed wording/version, and server-recorded preference changes are stored separately from study data. The owner can retrieve currently opted-in addresses; other readers cannot see them. This edition does not send update campaigns. Verification and password-reset messages are separate account messages.</p><h2>Offline copies</h2><p>Public reading downloads are cached separately from personal records. Account data remains in this browser for offline use. Browser storage and ordinary exports are readable by people with access to your browser profile or backup file. End-to-end encryption is not provided.</p><h2>Export and deletion</h2><p>Export your current progress and notebook in Settings. Sign out on the Account page. Account deletion removes synchronized account records, email preferences/consent history, and this browser’s corresponding account keys; other devices’ cached copies must be cleared on those devices. Guest data can be cleared separately in Settings.</p><h2>Feedback</h2><p>The feedback form collects your email address and the feedback or requests you type. Hosted submissions are handled by Netlify Forms for the site owner. Feedback is separate from your private study data and does not subscribe you to email updates.</p><h2>External sources</h2><p>Following an external source or recording link connects to that publisher’s website, which has its own policies. External recordings and readings require internet.</p><h2>Contact</h2><p>For questions about this website or information you submitted, use the <a href="feedback.html">feedback form</a>.</p></article>`;return;}
   let mode=kind==='release'?'sources':'drafts',q='',remote=[],roles=[],message='';if(window.OrthodoxAccounts.user()){try{[remote,roles]=await Promise.all([window.OrthodoxAccounts.reports('list'),window.OrthodoxAccounts.roles()]);}catch(error){message=error.message;}}
   const statuses=['submitted','investigating','needs-source','ready-for-review','reviewed','closed'];
   function draw(){root.innerHTML=`<h1>${kind==='release'?'Source and release inventory':'Editorial review'}</h1><p>Quotation matching verifies text against an identified source. Independent theological review, reproduction permission, and editorial approval are separate records. No independent theological review is claimed.</p><div class="tool-tabs"><button data-editor-mode="drafts" aria-pressed="${mode==='drafts'}">My correction drafts</button><button data-editor-mode="submitted" aria-pressed="${mode==='submitted'}">Submitted corrections</button><button data-editor-mode="sources" aria-pressed="${mode==='sources'}">Source inventory</button><button data-editor-mode="history" aria-pressed="${mode==='history'}">Revision history</button></div>${message?`<p role="status" class="notice">${esc(message)}</p>`:''}<div id="editor-content">${body()}</div>`;}
   function body(){if(mode==='drafts'){const items=window.OrthodoxStudyTools.get().corrections;return `<p>Drafts stay private until you submit them to a configured account service. Exporting a draft downloads a file; it sends nothing.</p><button data-editor-export>Export correction drafts</button>`+(items.length?items.map(item=>`<article class="editorial-item"><h2>${esc(item.title)}</h2><a href="${/^#\/[a-z0-9/-]+$/i.test(item.route)?item.route:'#/home'}">Open reading</a><p>${esc(item.text)}</p><p>Status: ${esc(item.status)}</p><button data-submit-correction="${item.id}" ${!window.OrthodoxAccounts.user()?'disabled':''}>Submit correction</button><button data-remove-correction="${item.id}">Remove draft</button></article>`).join(''):'<p>No drafts. Use “Report a correction” on a reading.</p>');}
     if(mode==='submitted')return '<p>'+esc(window.OrthodoxAccounts.user()?(roles.length?'Your assigned roles: '+roles.join(', '):'Reader account: your own submissions are visible.'):'Sign in to view submissions. Accounts must first be configured.')+'</p>'+remote.map(item=>`<article class="editorial-item"><h2>${esc(item.title)}</h2><p>${esc(item.text)}</p><p>${esc(item.status)} · ${esc(item.created_at)}</p>${roles.length?`<label>Review note<textarea data-review-note="${esc(item.id)}" maxlength="20000">${esc(item.review_note)}</textarea></label><label>Status<select data-review-status="${esc(item.id)}">${statuses.filter(s=>s!=='reviewed'||roles.includes('reviewer')).map(s=>`<option ${s===item.status?'selected':''}>${s}</option>`).join('')}</select></label><button data-save-review="${esc(item.id)}">Save workflow record</button>`:`<p>${esc(item.review_note)}</p>`}</article>`).join('');
     if(mode==='history')return '<p>App content changes are distinct from your private study activity. A workflow record does not itself change a published reading.</p>'+(release?.revisions||[]).map(r=>`<article class="notebook-item"><h2>${esc(r.version)} · ${esc(r.date)}</h2><p>${esc(r.description)}</p><p>${esc(r.reviewStatus)}</p></article>`).join('');
     const records=(release?.sources||[]).filter(s=>[s.title,s.author,s.rights,s.distribution].join(' ').toLowerCase().includes(q.toLowerCase()));return `<p>${release?.sources?.length||0} source records. This inventory records the existing reproduction basis and unresolved distribution limits. It does not certify worldwide permission.</p><label>Search sources<input id="release-search" type="search" value="${esc(q)}"></label><button data-release-export>Export source inventory</button><div class="release-scroll"><table class="release-table"><thead><tr><th>Source</th><th>Text verification</th><th>Reproduction basis / release action</th><th>Theological review</th></tr></thead><tbody>${records.map(s=>`<tr><td>${esc(s.title)}<br>${esc(s.author)}</td><td>${esc(s.verification)}</td><td>${esc(s.rights)}<br>${esc(s.distribution)}</td><td>Not recorded</td></tr>`).join('')}</tbody></table></div>`;}
   root.addEventListener('input',event=>{if(event.target.id==='release-search'){q=event.target.value;const selection=event.target.selectionStart;root.querySelector('#editor-content').innerHTML=body();const input=root.querySelector('#release-search');input.focus();input.setSelectionRange(selection,selection);}},{signal});
   root.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{if(button.dataset.editorMode){mode=button.dataset.editorMode;draw();}if(button.hasAttribute('data-editor-export'))window.OrthodoxAccounts.download({app:'the-orthodox-way',kind:'correction-drafts',drafts:window.OrthodoxStudyTools.get().corrections},'holy-apostolic-correction-drafts.json');if(button.hasAttribute('data-release-export'))window.OrthodoxAccounts.download(release,'holy-apostolic-source-inventory.json');if(button.dataset.removeCorrection){const d=window.OrthodoxStudyTools.get();d.corrections=d.corrections.filter(x=>x.id!==button.dataset.removeCorrection);window.OrthodoxStudyTools.save();draw();}if(button.dataset.submitCorrection){button.disabled=true;const item=window.OrthodoxStudyTools.get().corrections.find(x=>x.id===button.dataset.submitCorrection);const result=await window.OrthodoxAccounts.reports('submit',{route:item.route,title:item.title,text:item.text,status:'submitted'});item.status='submitted';window.OrthodoxStudyTools.save();remote.unshift(result[0]);message='Correction submitted. Your private notebook questions were not included.';draw();}if(button.dataset.saveReview){button.disabled=true;const id=button.dataset.saveReview,status=root.querySelector('[data-review-status="'+CSS.escape(id)+'"]').value,review_note=root.querySelector('[data-review-note="'+CSS.escape(id)+'"]').value;const result=await window.OrthodoxAccounts.reports('update',{id,status,review_note});remote=remote.map(r=>r.id===id?result[0]:r);message='Workflow record saved. Publication content has not been changed.';draw();}}catch(error){message=error.message;draw();}},{signal});draw();
 }
 function prayerTitle(value){return String(value?.title??value??'').replace(/\s*\(1982\)\s*$/u,'').replace(/\s*—\s*(?:full published order|published combined order|published order)\s*$/u,'').trim();}
 function unmount(){controller?.abort();controller=null;}
 return {load,mount,unmount,setSources:map=>{sourceMap=map;},sourceContext,prayerTitle};
})();
